CREATE FUNCTION app.current_tenant()
RETURNS bigint
LANGUAGE sql
IMMUTABLE
SET work_mem = '64MB'
AS $$
SELECT 1::bigint
$$;

CREATE VIEW app.my_documents WITH (security_invoker = true) AS
